function [faces, per] = fmr_faces(bx)
%FMR_FACES  The X, Y and Z rings' faces [m^2] and perimeters [m] in a box of sides bx [m].
%   bx: real[1][3] (passed a plain number)
%   returns faces: real[1][3] (passed a plain number)
%   returns per: real[1][3] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    faces = zeros(3, 1);
    per = zeros(3, 1);
    faces = [(bx(2) * bx(3)); (bx(1) * bx(3)); (bx(1) * bx(2))];
    per = [(2 * (bx(2) + bx(3))); (2 * (bx(1) + bx(3))); (2 * (bx(1) + bx(2)))];
end
